// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PreviewConversion) predicate.PreviewConversion {
	return predicate.PreviewConversion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PreviewConversion) predicate.PreviewConversion {
	return predicate.PreviewConversion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PreviewConversion) predicate.PreviewConversion {
	return predicate.PreviewConversion(sql.NotPredicates(p))
}
